// Package openapi post-processes the raw Swagger 2.0 specs generated by
// protoc-gen-openapiv2 into OpenAPI 3 specs with JSON:API envelope schemas. The
// Swagger 2.0 → OpenAPI 3 conversion is kin-openapi's openapi2conv (convert.go adds
// the API-key header schemes it is given and keeps each $ref's description and readOnly);
// the JSON:API envelope, the descriptor reading and the route table are this package's.
//
// The JSON:API envelope semantics (service name, base path, and per-resource
// single/collection keys) are declared in the proto via the jsonapi.v1
// annotations and read from a buf descriptor set — there is no hand-maintained
// service map. The package is generic: it carries zero per-service API data and
// reads whatever descriptor set it is given (see descriptor.go).
package openapi

import (
	"encoding/json"
	"fmt"
	"maps"
	"path/filepath"
	"sort"
	"strings"

	apperr "github.com/gt-tech-ai/knowledge-engine-toolkit/go/core/errors"
	"github.com/gt-tech-ai/knowledge-engine-toolkit/go/core/interfaces"
	"github.com/gt-tech-ai/knowledge-engine-toolkit/go/helpers"
)

// serviceConfig maps a target service to its JSON:API resource metadata.
type serviceConfig struct {
	// resources holds the service's JSON:API resources, keyed by resource type.
	resources map[string]resourceConfig

	// service is the directory name under the server dir (e.g. "library").
	service string

	// basePath is the REST base path (e.g. "/v1/library").
	basePath string
}

// resourceConfig describes a single JSON:API resource type. The keys are JSON
// (camelCase) property names as they appear in the generated OpenAPI schema.
type resourceConfig struct {
	// resourceType is the JSON:API `data.type` value (e.g. "users").
	resourceType string

	// singleKey is the response property holding one resource (e.g. "user");
	// empty for collection-only resources.
	singleKey string

	// collectionKey is the response property holding a resource list (e.g.
	// "users"); empty for single-only resources.
	collectionKey string

	// paginationKey is the response property holding pagination metadata; carried
	// for fidelity but inert (the collection envelope's shape is fixed).
	paginationKey string
}

// Result reports the per-service specs written and the proto packages skipped
// (those declaring no jsonapi.v1.service annotation).
type Result struct {
	// Written holds the output paths of every per-service OpenAPI spec written.
	Written []string
	// Skipped holds the input swagger file paths whose proto package declared no
	// jsonapi.v1.service annotation, so no service could be resolved for them.
	Skipped []string
}

// Convert reads every generated swagger file under inDir and writes a
// per-service JSON:API OpenAPI 3 spec under outDir, driven by the
// jsonapi.v1 annotations carried in the buf descriptor set at descriptorPath. Every
// read and write goes through fsys.
//
// headers maps each API-key security scheme every spec declares and requires to its
// request header (e.g. the identity headers a gateway injects); empty declares none.
//
// routes is the operation-keyed route table (from BuildRouteTable),
// keyed by service name; each service's entries drive the per-operation envelope.
// A nil/empty table makes every operation fall back to the by-resource-property
// response match, so callers that don't need per-operation enveloping (or that
// have no descriptor-derived table) get the prior behavior unchanged.
func Convert(
	fsys interfaces.FS,
	inDir, outDir, descriptorPath string,
	routes map[string][]RouteEntry,
	headers map[string]string,
) (Result, error) {
	// Discover all .swagger.json files under inDir first. With no swagger files
	// there is nothing to convert — this is a no-op rather than an error (a
	// failed `buf generate` upstream is the loud signal; an empty input dir is
	// not the converter's failure to report).
	swaggerFiles, err := findSwaggerFiles(fsys, inDir)
	if err != nil {
		return Result{}, apperr.Wrap(
			err,
			apperr.CodeInternal,
			"walk "+inDir,
		)
	}
	if len(swaggerFiles) == 0 {
		return Result{}, nil
	}

	fdsBytes, err := fsys.ReadFile(descriptorPath)
	if err != nil {
		return Result{}, apperr.Wrap(
			err,
			apperr.CodeInternal,
			"read descriptor "+descriptorPath,
		)
	}

	configs, pkgToService, err := readServiceConfigs(fdsBytes)
	if err != nil {
		return Result{}, apperr.Wrap(err, apperr.CodeInternal, "read service configs")
	}

	// Route each swagger file to its service via the proto package's
	// jsonapi.v1.service annotation. Multiple packages can map to one service
	// (several packages → one service); their swagger files merge into a
	// single per-service spec. Files whose package declares no service
	// annotation are skipped (e.g. ws/v1, retrieval/v1, jsonapi/v1).
	byService := make(map[string][]string)
	var skipped []string
	for _, sf := range swaggerFiles {
		rel, err := filepath.Rel(inDir, sf)
		if err != nil {
			return Result{}, apperr.Wrap(err, apperr.CodeInternal, "rel path")
		}
		pkgPath := filepath.ToSlash(filepath.Dir(rel))
		svc, ok := pkgToService[pkgPath]
		if !ok {
			skipped = append(skipped, sf)
			continue
		}
		byService[svc] = append(byService[svc], sf)
	}

	var written []string
	for svc, files := range byService {
		cfg, ok := configs[svc]
		if !ok {
			return Result{}, apperr.New(
				apperr.CodeInternal,
				fmt.Sprintf("no config for service %q", svc),
			)
		}

		// Merge all swagger specs across every package mapped to this service.
		merged, err := MergeSwaggerFiles(fsys, files)
		if err != nil {
			return Result{}, apperr.Wrap(
				err,
				apperr.CodeInternal,
				"merge service "+svc,
			)
		}

		outPath, err := processSpec(fsys, merged, outDir, cfg, routes[svc], headers)
		if err != nil {
			return Result{}, apperr.Wrap(
				err,
				apperr.CodeInternal,
				"process service "+svc,
			)
		}
		written = append(written, outPath)
	}

	sort.Strings(written)
	sort.Strings(skipped)
	return Result{Written: written, Skipped: skipped}, nil
}

// findSwaggerFiles returns every *.swagger.json file under dir, walked through fsys in
// lexical order.
func findSwaggerFiles(fsys interfaces.FS, dir string) ([]string, error) {
	entries, err := fsys.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, e := range entries {
		p := filepath.Join(dir, e.Name())
		if e.IsDir() {
			sub, err := findSwaggerFiles(fsys, p)
			if err != nil {
				return nil, err
			}
			files = append(files, sub...)
			continue
		}
		if strings.HasSuffix(e.Name(), ".swagger.json") {
			files = append(files, p)
		}
	}
	return files, nil
}

// MergeSwaggerFiles reads multiple swagger JSON files and merges their paths
// and definitions into a single spec. Files are sorted first so the base file
// (which provides info/host/etc. verbatim) is deterministic regardless of the
// caller's order — the file list is built from map iteration, which otherwise
// flipped the merged info.title between runs. Others contribute their paths and
// definitions. The files are read through fsys.
func MergeSwaggerFiles(fsys interfaces.FS, files []string) (map[string]any, error) {
	files = append([]string(nil), files...)
	sort.Strings(files)

	var merged map[string]any

	for _, f := range files {
		data, err := fsys.ReadFile(f)
		if err != nil {
			return nil, apperr.Wrap(err, apperr.CodeInternal, "read "+f)
		}

		var spec map[string]any
		if err := json.Unmarshal(data, &spec); err != nil {
			return nil, apperr.Wrap(
				err,
				apperr.CodeInternal,
				"parse "+f,
			)
		}

		if merged == nil {
			merged = spec
			continue
		}

		// Merge paths.
		if paths := helpers.GetMap(spec, "paths"); paths != nil {
			mergedPaths := helpers.GetMap(merged, "paths")
			if mergedPaths == nil {
				mergedPaths = make(map[string]any)
				merged["paths"] = mergedPaths
			}
			maps.Copy(mergedPaths, paths)
		}

		// Merge definitions.
		if defs := helpers.GetMap(spec, "definitions"); defs != nil {
			mergedDefs := helpers.GetMap(merged, "definitions")
			if mergedDefs == nil {
				mergedDefs = make(map[string]any)
				merged["definitions"] = mergedDefs
			}
			maps.Copy(mergedDefs, defs)
		}
	}

	return merged, nil
}

// processSpec converts a merged Swagger 2.0 spec to a JSON:API OpenAPI 3
// spec and writes it to <outDir>/<service>/docs/openapi.json, returning the
// path written. routes is the service's operation-keyed route table
// driving the per-operation envelope. The spec is written through fsys.
func processSpec(
	fsys interfaces.FS,
	swagger map[string]any,
	outDir string,
	cfg serviceConfig,
	routes []RouteEntry,
	headers map[string]string,
) (string, error) {
	// Convert Swagger 2.0 → OpenAPI 3.
	oas3, err := convertToOAS3(swagger, cfg, headers)
	if err != nil {
		return "", err
	}

	// Rewrite response schemas for JSON:API.
	rewriteForJSONAPI(oas3, cfg, routes)

	// Write output.
	outputDir := filepath.Join(outDir, cfg.service, "docs")
	if err := fsys.MkdirAll(outputDir, 0o755); err != nil {
		return "", apperr.Wrap(
			err,
			apperr.CodeInternal,
			"create "+outputDir,
		)
	}

	outputPath := filepath.Join(outputDir, "openapi.json")
	out, err := json.MarshalIndent(oas3, "", "  ")
	if err != nil {
		return "", apperr.Wrap(err, apperr.CodeInternal, "marshal output")
	}
	out = append(out, '\n')

	if err := fsys.WriteFile(outputPath, out, 0o600); err != nil {
		return "", apperr.Wrap(
			err,
			apperr.CodeInternal,
			"write "+outputPath,
		)
	}

	return outputPath, nil
}
